/**
 * Installed-version protocol capability probe for the Codex app-server.
 *
 * The official docs describe `dynamicTools` and `item/tool/call` as
 * experimental, and the generated schema is version-specific. A similar flag
 * name is not proof of support, so availability is derived from the schema
 * generated by the INSTALLED CLI (`codex app-server generate-json-schema`),
 * not from documentation alone.
 *
 * Required facts:
 * - `thread/start` accepts `dynamicTools` (the only documented client-side
 *   tool declaration), and
 * - `DynamicToolCallParams` / `DynamicToolCallResponse` exist (the
 *   `item/tool/call` request/response flow).
 *
 * When either is missing, the adapter cannot guarantee that a coached run
 * exposes only the two read-only domain tools and must stay unavailable.
 *
 * More importantly, BOTH can be present and still be insufficient: dynamic
 * tools are additive, so built-in file/shell/network/MCP/hook/plugin tools
 * remain unless the installed version offers a verified inventory exclusion.
 * This probe therefore reports `supported: false` with
 * `builtin-isolation-unproven` until such evidence exists. That is the exact
 * missing protocol condition; documentation alone is not evidence.
 */
import { spawn } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

export interface CodexAppServerSupport {
  supported: boolean;
  /**
   * Only true when there is positive, version-specific evidence that the
   * installed app-server can exclude its entire built-in tool inventory
   * (shell/file/network, apply_patch, MCP, hooks, plugins). `dynamicTools`
   * alone never establishes this.
   */
  builtinIsolationVerified?: boolean;
  /** Installed CLI version when known (from `codex --version` or argv probe). */
  version?: string;
  /** Concrete missing capability when unsupported. */
  gap?: string;
  /** True when the CLI itself could not be executed. */
  unavailable?: boolean;
}

interface JsonSchemaDocument {
  definitions?: Record<string, unknown>;
  $defs?: Record<string, unknown>;
}

function definitionsOf(document: unknown): Record<string, unknown> {
  if (typeof document !== "object" || document === null) return {};
  const doc = document as JsonSchemaDocument;
  return doc.definitions ?? doc.$defs ?? {};
}

function propertiesOf(definition: unknown): Record<string, unknown> {
  if (typeof definition !== "object" || definition === null) return {};
  const properties = (definition as { properties?: unknown }).properties;
  return typeof properties === "object" && properties !== null
    ? (properties as Record<string, unknown>)
    : {};
}

/**
 * Pure check over the generated v2 schema bundle. Exported so tests can use a
 * fixture without spawning a CLI; the result is evidence tied to that exact
 * schema document.
 */
export function inspectCodexAppServerSchema(document: unknown): CodexAppServerSupport {
  const definitions = definitionsOf(document);
  const threadStart = definitions.ThreadStartParams;
  const hasDynamicTools = Object.prototype.hasOwnProperty.call(
    propertiesOf(threadStart),
    "dynamicTools",
  );
  if (!hasDynamicTools) {
    return {
      supported: false,
      builtinIsolationVerified: false,
      gap: "installed codex app-server schema does not expose thread/start.dynamicTools",
    };
  }
  for (const name of ["DynamicToolCallParams", "DynamicToolCallResponse"]) {
    if (definitions[name] === undefined) {
      return {
        supported: false,
        builtinIsolationVerified: false,
        gap: `installed codex app-server schema is missing ${name}`,
      };
    }
  }
  // dynamicTools is ADDITIVE. It tells the client about extra tools but does
  // not remove shell/file/network/apply_patch/MCP/hook/plugin tools, and the
  // installed schema exposes no inventory-exclusion or "no built-ins" proof.
  // A read-only sandbox still allows arbitrary file reads and exfiltration,
  // so the backend must stay unavailable until such proof exists.
  return {
    supported: false,
    builtinIsolationVerified: false,
    gap:
      "builtin-isolation-unproven: dynamicTools adds client tools but does not disable built-in shell/file/network/MCP/hook/plugin tools",
  };
}

interface ProbeOptions {
  binary?: string;
  timeoutMs?: number;
  /** Test seam: returns the generated v2 schema JSON text. */
  generateSchema?: (binary: string) => Promise<string>;
}

async function runGenerateJsonSchema(binary: string, timeoutMs: number): Promise<string> {
  const dir = await mkdtemp(join(tmpdir(), "fit-trace-codex-schema-"));
  try {
    await new Promise<void>((resolve, reject) => {
      let settled = false;
      const done = (error?: Error): void => {
        if (settled) return;
        settled = true;
        if (error !== undefined) reject(error);
        else resolve();
      };
      let child;
      try {
        child = spawn(binary, ["app-server", "generate-json-schema", "--out", dir], {
          stdio: ["ignore", "ignore", "ignore"],
          timeout: timeoutMs,
        });
      } catch {
        done(new Error("spawn-failed"));
        return;
      }
      child.on("error", () => done(new Error("spawn-failed")));
      child.on("close", (code) => done(code === 0 ? undefined : new Error("probe-failed")));
      const timer = setTimeout(() => {
        try {
          child.kill("SIGKILL");
        } catch {
          // Best-effort.
        }
        done(new Error("probe-timeout"));
      }, timeoutMs);
      timer.unref?.();
    });
    return await readFile(join(dir, "codex_app_server_protocol.v2.schemas.json"), "utf8");
  } finally {
    await rm(dir, { recursive: true, force: true }).catch(() => undefined);
  }
}

/** Probe the installed CLI. Never calls a model; only generates its schema. */
export async function probeCodexAppServer(options: ProbeOptions = {}): Promise<CodexAppServerSupport> {
  const binary = options.binary ?? "codex";
  try {
    const text = await (options.generateSchema ?? ((name) => runGenerateJsonSchema(name, options.timeoutMs ?? 10000)))(binary);
    const document = JSON.parse(text) as unknown;
    return inspectCodexAppServerSchema(document);
  } catch {
    return {
      supported: false,
      unavailable: true,
      gap: "codex CLI is not installed or could not generate its app-server schema",
    };
  }
}
